"""Publish measured checks and an explicitly unreviewed geographic audit template."""
from pathlib import Path
import json,html,shutil
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/plano_city/accessibility';DEST=ROOT/'netlify_site/src'

def run():
 environment=json.load(open(ROOT/'output/plano_city/environment_coverage.json'));base=json.load(open(OUT/'evaluation_baseline.json'));sensitivity=json.load(open(OUT/'evaluation_sensitivity.json'))
 b=pd.read_csv(OUT/'block_accessibility.csv',dtype={'GEOID20':str});positive=pd.to_numeric(b.HU100)>0
 candidates=[]
 for kind,rows in [('low_cost',b[positive].sort_values('access_essential_mean_equiv_min')),('high_cost',b[positive].sort_values('access_essential_mean_equiv_min',ascending=False)),('large_snap_gap',b[positive].sort_values('access_snap_gap_m',ascending=False)),('unreachable_reference',b[positive&b.access_essential_mean_equiv_min.isna()]),('north',b[positive].sort_values('block_latitude',ascending=False)),('south',b[positive].sort_values('block_latitude')),('east',b[positive].sort_values('block_longitude',ascending=False)),('west',b[positive].sort_values('block_longitude'))]:
  used={r['GEOID20'] for r in candidates}
  for r in rows.itertuples():
   if str(r.GEOID20) in used:continue
   candidates.append({'GEOID20':str(r.GEOID20),'sample_reason':kind,'snap_gap_m':r.access_snap_gap_m,'review_status':'NOT REVIEWED','entrance_and_connector_check':'','crossings_and_barriers_check':'','public_access_and_destination_check':'','trail_vs_road_observation':'','notes':'','app_url':'https://empathmaps.netlify.app/app.html?categories=hindu_temple,supermarket,pharmacy&block='+str(r.GEOID20)})
   break
 pd.DataFrame(candidates).to_csv(OUT/'manual_route_review_template.csv',index=False)
 scope={'city_blocks':len(b),'tree_prediction_blocks':environment['city_blocks_with_canopy'],'temperature_observed_blocks':environment['city_blocks_with_temperature'],'complete_accessibility_blocks':int(b.access_essential_mean_equiv_min.notna().sum()),'unreachable_references':int(b.access_essential_mean_equiv_min.isna().sum()),'snap_gaps_over_100m':int(b.access_snap_gap_m.gt(100).sum()),'housing_positive_unreachable':int((positive&b.access_essential_mean_equiv_min.isna()).sum()),'raw_city_network_edges':json.load(open(OUT/'accessibility_method.json'))['weighted_edges'],'manual_reviews_completed':0}
 (OUT/'evaluation_coverage.json').write_text(json.dumps(scope,indent=2))
 for name in ['evaluation_baseline.json','evaluation_sensitivity.json','evaluation_coverage.json','manual_route_review_template.csv']:
  shutil.copy2(OUT/name,DEST/'data'/name)
 rows=''.join('<tr><td>'+html.escape(k.replace('_',' '))+'</td><td>'+str(v)+'</td></tr>' for k,v in scope.items())
 page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EmPath · Evaluation</title><style>body{max-width:900px;margin:35px auto;padding:0 22px;font:16px/1.65 system-ui;color:#183c35;background:#f3f5f0}h1,h2{font-family:Georgia,serif}section{background:white;padding:22px;margin:20px 0;border:1px solid #d2ded5;border-radius:10px}table{border-collapse:collapse;width:100%}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}a{color:#185b47}.notice{background:#fff2d8;padding:15px;border-left:4px solid #d59422}</style><nav><a href="app.html">Category selector and routes</a> · <a href="index.html">Maps</a> · <a href="method.html">Equation</a></nav><h1>What has been evaluated?</h1><p>Citywide computational checks and sensitivity tests are complete. Independent walking-condition and local preference validation remain unfinished.</p><section><h2>1. Data coverage and connection flags</h2><table>'''+rows+'''</table><p>Tree coverage is prediction coverage, not prediction accuracy. Missing temperature is handled by flagged block proxies; it is not presented as a direct measurement. Snap gaps and disconnected references need entrance and barrier review.</p></section><section><h2>2. Calculation and interface checks</h2><ul><li>Finite, nonnegative edge weights and the documented cost formula.</li><li>Reverse multi-source category costs match forward Dijkstra spot checks.</li><li>Client-displayed route weights sum to the same cached block score.</li><li>Category selection, empty selections, ranking filters, route highlighting, category changes and CSV download tested in Chrome.</li><li>City boundary and one-kilometer routing/destination buffer are explicit.</li></ul><p>These checks establish implementation consistency. They do not certify real-world sidewalk access or safety.</p></section><section><h2>3. Time-only versus friction-weighted recommendations</h2><p>On the same supported graph and eligible housing-block set, essential-service ranking correlation is <strong>'''+f'{sensitivity["time_only_vs_friction_residential"]["spearman"]:.3f}'+'''</strong>. <strong>19 of the top 20 blocks</strong> overlap. Distance is therefore a major driver under this bounded penalty model.</p><p>Prioritizing canopy, traffic or heat with 60/20/20 factor weights retained the same top-20 set in this test. This is a robustness observation, not proof that the model reflects people's preferences.</p><p><a href="data/evaluation_baseline.json">Baseline results</a> · <a href="data/evaluation_sensitivity.json">Weight sensitivity results</a></p></section><section><h2>4. Geographic review still required</h2><p>Inspect the ranked routes, especially busy-road sections, missing connectors and park entrances. Compare official trail geometry, aerial/street imagery and available access metadata. Include easy and difficult cases across the city.</p><p><a href="data/manual_route_review_template.csv" download>Download the pending route-review template</a>. Its entries are labeled NOT REVIEWED; no manual pass is implied.</p><ol><li>Verify plausible block and destination entrances.</li><li>Check crossings, barriers, public access and network discontinuities.</li><li>Inspect whether apparent trail advantages agree with imagery and source data.</li><li>Record discrepancies and rerun routing after justified fixes.</li></ol></section><p class="notice">Without independent Plano route-choice or comfort observations, this project cannot report accuracy against residents' perceived walking friction. Published Singapore preference results are transferable research context, not local validation. The GeoAI tree predictions also require a separate independently labeled image sample to quantify segmentation accuracy.</p>'''
 benchmark=OUT/'route_benchmark_city_method.json'
 if benchmark.exists():
  r=json.loads(benchmark.read_text())
  for name in ['route_benchmark_city.csv','route_benchmark_city_method.json']:shutil.copy2(OUT/name,DEST/'data'/name)
  extra='<section><h2>Route-level comparison: same destination</h2><p>Six spatially spread housing-positive origins and three essential services give '+str(r['pairs'])+' same-destination comparisons. '+str(r['different_routes'])+' use different edges under friction weighting. Mean extra ordinary walking time: '+format(r['mean_extra_actual_walk_minutes']*60,'.1f')+' seconds. '+str(r['pairs_with_less_busy_road_length'])+' reduce busy-road-proximity length. These are small-sample exposure comparisons, not validated preferences.</p><p><a href="data/route_benchmark_city.csv">Trip comparisons</a> · <a href="data/route_benchmark_city_method.json">Sampling method</a></p></section>'
  page=page.replace('<section><h2>4. Geographic review still required',extra+'<section><h2>4. Geographic review still required')
 boundary=OUT/'boundary_buffer_method.json'
 if boundary.exists():
  q=json.loads(boundary.read_text())
  extra='<section id="boundary"><h2>Boundary coverage: 1 km versus 3 km</h2><p>The larger walking network contains '+format(q['larger_graph_edges'],',')+' directed edges and '+str(q['additional_candidates'])+' additional destination candidates. Across the current catalog, '+format(q['flagged_blocks'],',')+' blocks have at least one category whose fastest trip decreases by more than one minute. Existing snapped junction IDs were retained to avoid changing the origin or destination connections during the comparison.</p><p>This is a time-only acquisition-support test, not an updated friction model. New environmental features and weights are required before expanded routes can replace production scores. Affected selected-category recommendations are flagged in the app. Three kilometers is not proof of convergence, and real remoteness can also cause high costs.</p><a href="data/boundary_buffer_comparison.csv">Download category-by-block comparisons</a> · <a href="data/boundary_buffer_method.json">Method and limitations</a></section>'
  page+=extra
 social=DEST/'data/social_context_method.json'
 if social.exists():
  q=json.loads(social.read_text());r=q['statistics']
  page+='<section><h2>Population, affordability and demographic comparison</h2><p>Population-density versus essential walking cost rank correlation: '+format(r['block_density_access_spearman'],'.3f')+' across '+str(r['density_matched_blocks'])+' eligible non-border residential blocks. Density alone therefore does not reproduce the current essential-access rankings. This descriptive comparison is not a causal or preference validation.</p><p>ACS context uses '+str(r['block_groups'])+' block groups; disability uses tract geometry. Missing or inapplicable estimates stay unavailable; popups show 90% margins of error. Area medians are not individual or current listing prices.</p><a href="context.html">Explore comparisons</a> · <a href="data/social_context_method.json">Source tables, methods and correlations</a></section>'
 (DEST/'validation.html').write_text(page);return scope
if __name__=='__main__':print(json.dumps(run(),indent=2))
